const fs=require('fs'), vm=require('vm'), crypto=require('crypto');
const modulePath=process.argv[1] || 'DOMUS_MercadoPagoSync.gs';
const code=fs.readFileSync(modulePath,'utf8');
const context={console}; vm.createContext(context); vm.runInContext(code,context);
const results=[];
function test(name,fn){try{fn();results.push({name,status:'PASS'})}catch(e){results.push({name,status:'FAIL',error:String(e)})}}
function equal(a,b){if(a!==b)throw Error(`${a} != ${b}`)}
function rejects(fn,errorCode){try{fn()}catch(e){equal(e.dmpCode,errorCode);return}throw Error('Did not reject')}
function row(id,name,category,solar,lunar,status='Aprobado'){return[id,name,category,solar,lunar,status]}
function emptyWorkbook(){const products={},categories={};for(let i=5;i<=997;i++)products[i]={row:i,name:'',price:'',category:'',empty:true};for(let i=6;i<=205;i++)categories[i]='';return{products,categories}}
const syntheticRows=Array.from({length:93},(_,i)=>row('PROD-'+String(i+1).padStart(3,'0'),'Producto prueba '+(i+1),'Categoria prueba',40,45));
test('93 approved products produce 186 unique variants in two phases',()=>{const s=context.DMP_source_(syntheticRows);equal(s.variants.length,186);equal(new Set(s.variants.map(v=>v.key)).size,186);equal(new Set(s.variants.map(v=>v.phase)).size,2)});
test('60-character exported name accepted and 61 rejected',()=>{context.DMP_source_([row('PROD-001','A'.repeat(44),'Categoria prueba',40,45)]);rejects(()=>context.DMP_source_([row('PROD-001','A'.repeat(45),'Categoria prueba',40,45)]),'EXPORTED_NAME_TOO_LONG')});
test('Price range accepted and zero, string, NaN, boolean rejected',()=>{for(const v of [.01,999999999])equal(context.DMP_price_(v,'BAD_PRICE'),v);for(const v of [0,'40',NaN,true])rejects(()=>context.DMP_price_(v,'BAD_PRICE'),'BAD_PRICE')});
test('994 exported rows exceed the 993-row capacity',()=>{const rows=Array.from({length:497},(_,i)=>row('PROD-'+String(i+1).padStart(3,'0'),'Producto prueba '+i,'Categoria prueba',40,45));rejects(()=>context.DMP_source_(rows),'PRODUCT_CAPACITY_EXCEEDED')});
test('A 201st category is rejected without replacing existing categories',()=>{const wb=emptyWorkbook();for(let i=6;i<=205;i++)wb.categories[i]='Categoria '+i;const s=context.DMP_source_([row('PROD-001','Producto prueba','Categoria nueva',40,45)]);rejects(()=>context.DMP_plan_(s,wb,null),'CATEGORY_CAPACITY_EXCEEDED')});
test('An empty product source does not manufacture supplier or product rows',()=>{const p=context.DMP_plan_(context.DMP_source_([]),emptyWorkbook(),null);equal(p.changes.length,0);equal(p.manifest.products.length,0)});
test('A product pending approval is excluded from newly generated rows',()=>{const p=context.DMP_plan_(context.DMP_source_([row('PROD-001','Producto prueba','Categoria prueba',40,45,'Pendiente')]),emptyWorkbook(),null);equal(p.changes.length,0);equal(p.pending,1)});
test('Bootstrap rejects equal names with conflicting prices',()=>{const wb=emptyWorkbook(),s=context.DMP_source_([row('PROD-001','Producto prueba','Categoria prueba',40,45)]);wb.products[5]={row:5,name:s.variants[0].name,price:99,category:'Categoria prueba',empty:false};rejects(()=>context.DMP_plan_(s,wb,null),'BOOTSTRAP_MISMATCH')});
const failed=results.filter(r=>r.status!=='PASS').length;
console.log(JSON.stringify({code_sha256:crypto.createHash('sha256').update(code).digest('hex'),passed:results.length-failed,failed,results},null,2));
if(failed)process.exitCode=1;
